head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25303";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — certification

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil25303.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_9", fn: function(){ return (!(String(((dma_pageContext.get("certification") ?? "")) == null ? '' : ((dma_pageContext.get("certification") ?? ""))).length === 0)); } }, { id: "tr_10", fn: function(){ return (!(String(((dma_pageContext.get("certification") ?? "")) == null ? '' : ((dma_pageContext.get("certification") ?? ""))).length === 0)); } }, { id: "tr_13", fn: function(){ return (!(String(((dma_pageContext.get("certification") ?? "")) == null ? '' : ((dma_pageContext.get("certification") ?? ""))).length === 0)); } }, { id: "tr_16", fn: function(){ return (!(String(((dma_pageContext.get("certification") ?? "")) == null ? '' : ((dma_pageContext.get("certification") ?? ""))).length === 0)); } }, { id: "tr_19", fn: function(){ return (!(String(((dma_pageContext.get("certification") ?? "")) == null ? '' : ((dma_pageContext.get("certification") ?? ""))).length === 0)); } }, { id: "c_otherwise_22", fn: function(){ return (!((!(String(((dma_pageContext.get("certification") ?? "")) == null ? '' : ((dma_pageContext.get("certification") ?? ""))).length === 0)))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb2", fn: function () { return String((String(String(dma_certification.get("certEndDd")) == null ? '' : String(dma_certification.get("certEndDd"))) === '' ? '' : String("yyyy-MM-dd").replace(/yyyy/g, String(dma_certification.get("certEndDd")).slice(0,4)).replace(/MM/g, String(dma_certification.get("certEndDd")).slice(4,6)).replace(/dd/g, String(dma_certification.get("certEndDd")).slice(6,8)).replace(/HH/g, String(dma_certification.get("certEndDd")).slice(8,10)).replace(/mm/g, String(dma_certification.get("certEndDd")).slice(10,12)).replace(/ss/g, String(dma_certification.get("certEndDd")).slice(12,14)))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_self_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25303.btn_self_onclick' }); }
};
